SELECT row_to_json(x) FROM (SELECT (SELECT count(*) FROM "Equipments") AS "totalEquipments",(SELECT count(*) FROM "Equipments" WHERE "Estado"='Disponible') AS "availableEquipments",(SELECT count(*) FROM "Equipments" WHERE "Estado"='Prestado') AS "loanedEquipments",(SELECT count(*) FROM "Equipments" WHERE "Estado"='Mantenimiento') AS "maintenanceEquipments",(SELECT count(*) FROM "Equipments" WHERE "Estado"='Baja') AS "decommissionedEquipments",(SELECT count(*) FROM "Loans") AS "totalLoans",(SELECT "AreaPrestamo" FROM "Loans" GROUP BY "AreaPrestamo" ORDER BY count(*) DESC,"AreaPrestamo" LIMIT 1) AS "areaConMayorUso",(SELECT count(*) FROM "Loans" GROUP BY "AreaPrestamo" ORDER BY count(*) DESC,"AreaPrestamo" LIMIT 1) AS "areaConMayorUsoCantidad") x;
SELECT coalesce(json_agg(x),'[]'::json) FROM (SELECT "AreaPrestamo" AS area,count(*) AS "totalLoans",count(*) FILTER(WHERE "FechaDevolucion" IS NULL) AS "activeLoans" FROM "Loans" WHERE "AreaPrestamo"<>'' GROUP BY "AreaPrestamo" ORDER BY count(*) DESC,"AreaPrestamo") x;
SELECT coalesce(json_agg(x),'[]'::json) FROM (SELECT e."Id" AS "equipmentId",e."Nombre" AS nombre,e."CodigoPatrimonial" AS "codigoPatrimonial",e."Categoria" AS categoria,e."Marca" AS marca,count(*) AS "timesUsed" FROM "Loans" l JOIN "Equipments" e ON e."Id"=l."EquipoId" GROUP BY e."Id" ORDER BY count(*) DESC,e."CodigoPatrimonial" LIMIT 5) x;
